const $=id=>document.getElementById(id);const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=v=>Number(v||0).toLocaleString('ru-RU');const money=v=>`$${Number(v||0).toFixed(2)}`;function eventLink(x){const slug=esc(x?.event_slug||x?.slug||''),url=x?.event_url?esc(x.event_url):'',start=x?.event_start?new Date(x.event_start):null,end=x?.event_end?new Date(x.event_end):null,label=start&&end?`${start.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}–${end.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}`:slug;return url?`<a class="event-link" href="${url}" target="_blank" rel="noopener noreferrer">${esc(label)}</a><br><small>${slug}</small>`:slug}const colors={bybit:'#ffbe55',okx:'#70a7ff',pyth:'#a8ee64',chainlink_rtds:'#36d6c9',chainlink_twap_60s:'#36d6c9'};const tableLabels={events:'Polymarket · события',event_targets:'Price to Beat по событиям',markets:'Polymarket · контракты',market_snapshots:'Polymarket · стакан и вероятность',future_event_snapshots:'Следующее событие · pre-open стакан',next_event_forecasts:'Прогноз следующего события',external_prices:'Внешние цены и oracle',training_examples:'Размеченные итоги',action_value_examples:'Примеры чистого PnL действий',model_decisions:'Решения торговых моделей',paper_positions:'Позиции demo-бота',paper_orders:'Исполнения demo-заявок',paper_sessions:'Бюджет demo-сессий',paper_equity_snapshots:'История demo-капитала',live_positions:'Позиции LIVE-бота',live_orders:'Реальные CLOB-заявки',live_execution_errors:'Ошибки LIVE-исполнения',source_metrics:'Задержки источников',raw_messages:'Сырые технические сообщения',strategy_labels:'Оценка решений стратегии',collector_runs:'Запуски сборщика'};
