function renderModelComparison(models){const rows=[...(models.paper_comparison||[])],sort=$('comparisonSort').value||'net_pnl_usdc';rows.sort((a,b)=>Number(b[sort]||0)-Number(a[sort]||0));$('modelComparisonBody').innerHTML=rows.length?rows.map(m=>`<tr><td><strong>${esc(m.model)}</strong><br><small>${esc(m.provider)}</small></td><td>${num(m.trades)}</td><td class="${Number(m.max_direction_share)>.8?'negative':''}">${num(m.up_entries)} / ${num(m.down_entries)}</td><td>${(Number(m.win_rate)*100).toFixed(1)}%</td><td>${(Number(m.wilson_lower)*100).toFixed(1)}–${(Number(m.wilson_upper)*100).toFixed(1)}%</td><td class="${Number(m.net_pnl_usdc)>0?'positive':Number(m.net_pnl_usdc)<0?'negative':''}">${money(m.net_pnl_usdc)}</td><td>${Number(m.profit_factor||0).toFixed(2)}</td><td>${money(m.expectancy_usdc)}</td><td>${money(m.max_drawdown_usdc)}</td><td title="${num(m.calibration_events)} размеченных входов">${m.live_roc_auc==null?'—':Number(m.live_roc_auc).toFixed(3)}</td><td title="${num(m.calibration_events)} размеченных входов">${m.live_pr_auc==null?'—':Number(m.live_pr_auc).toFixed(3)}</td><td>${m.statistically_positive?badge('ПОЛОЖИТЕЛЬНО ПОДТВЕРЖДЕНО','ok'):badge('ВЫБОРКА МАЛА / CI≤0','warn')}</td></tr>`).join(''):'<tr><td colspan="12" class="empty">Для межмодельного сравнения нужны завершённые paper-сделки разных моделей.</td></tr>';renderModelEquity(models.equity_curves||{});renderModelHealth(models.health||{},models.walk_forward_v8||{})}
function renderModelHealth(health,walk){const models=health.models||{},gate=walk.production_gate||{},walkCard=walk.total_test_events?`<div class="health-model-card"><strong>Walk-forward v8 · ${gate.passed?'GATE PASSED':'DEMO ONLY'}</strong><span>${num(walk.total_test_events)} OOS событий · ${num(walk.total_trades)} сделок · PnL ${money(walk.total_net_pnl)}</span><span>ROC-AUC ${Number(walk.mean_roc_auc||0).toFixed(3)} · PR-AUC ${walk.mean_pr_auc==null?'—':Number(walk.mean_pr_auc).toFixed(3)} · Brier ${Number(walk.mean_brier||0).toFixed(3)} · положительных окон ${num(gate.positive_folds)}/${num(gate.total_folds)}</span><span class="${gate.passed?'':'alert'}">${gate.passed?'критерии production выполнены':'production запрещён: CI/выборка/стабильность не прошли gate'}</span></div>`:'';$('modelHealthGrid').innerHTML=walkCard+Object.entries(models).map(([name,value])=>{const w=value.windows?.['30']||{},alerts=value.alerts||[];return `<div class="health-model-card"><strong>${esc(name)}</strong><span>30 событий · PnL ${money(w.net_pnl)} · ROC-AUC ${w.roc_auc==null?'—':Number(w.roc_auc).toFixed(3)} · PR-AUC ${w.pr_auc==null?'—':Number(w.pr_auc).toFixed(3)} · Brier ${w.brier==null?'—':Number(w.brier).toFixed(3)}</span><span>Bootstrap CI lower ${w.bootstrap_ci95_lower==null?'—':money(w.bootstrap_ci95_lower)} · Up/Down ${num(w.up)}/${num(w.down)}</span><span class="${alerts.length?'alert':''}">${alerts.length?esc(alerts.join(' · ')):'дрейф не обнаружен'}</span></div>`}).join('');const shadow=health.shadow_leaderboard||[];$('shadowLeaderboardBody').innerHTML=shadow.length?shadow.map(x=>`<tr><td>${esc(x.model_name)}</td><td title="${esc(x.first_event)} → ${esc(x.last_event)}">${num(x.samples)}</td><td>${num(x.trades)}</td><td>${num(x.up)} / ${num(x.down)}</td><td class="${Number(x.net_pnl)>0?'positive':Number(x.net_pnl)<0?'negative':''}">${money(x.net_pnl)}</td><td>${money(x.expectancy)}</td><td>${money(x.max_drawdown)}</td><td>${x.roc_auc==null?'—':Number(x.roc_auc).toFixed(3)}</td><td>${x.pr_auc==null?'—':Number(x.pr_auc).toFixed(3)}</td><td>${x.brier==null?'—':Number(x.brier).toFixed(3)}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">Shadow-прогнозы появятся после расчёта новых независимых событий.</td></tr>'}
function renderOfflineComparison(models){const source=(models.offline_report||{}).models||{},rows=Object.entries(source).map(([key,value])=>({key,...value})),sort=$('offlineSort').value||'accuracy';rows.sort((a,b)=>sort==='brier_asc'?Number(a.brier??999)-Number(b.brier??999):Number(b[sort]??-1)-Number(a[sort]??-1));$('offlineComparisonBody').innerHTML=rows.length?rows.map(m=>`<tr><td><strong>${esc(m.name||m.key)}</strong></td><td>${num(m.events)}</td><td>${m.accuracy==null?'—':(Number(m.accuracy)*100).toFixed(1)+'%'}</td><td>${m.roc_auc==null?'—':Number(m.roc_auc).toFixed(3)}</td><td>${m.pr_auc==null?'—':Number(m.pr_auc).toFixed(3)}</td><td>${m.brier==null?'—':Number(m.brier).toFixed(3)}</td><td>${m.log_loss==null?'—':Number(m.log_loss).toFixed(3)}</td><td>${(Number(m.coverage||0)*100).toFixed(1)}%</td><td>${num(m.trades)}</td><td class="${Number(m.net_pnl_usdc)>0?'positive':Number(m.net_pnl_usdc)<0?'negative':''}">${money(m.net_pnl_usdc)}</td><td>${esc(m.small_sample_warning||((m.events||0)<100?'малая выборка':'holdout'))}</td></tr>`).join(''):'<tr><td colspan="11" class="empty">Offline-отчёт ещё не рассчитан.</td></tr>'}
function renderHistoryContext(models){const variants=models.history_context?.variants||{},hyp=models.loss_reversal?.trading_hypothesis||{};$('historyContextGrid').innerHTML=Object.entries(variants).map(([key,v])=>{const m=v.mean||{};return `<div class="health-model-card"><strong>${esc(key.replace('history_','История: '))} событий</strong><span>${num(v.events)} событий · ${num((v.folds||[]).length)} walk-forward фолдов</span><span>ROC-AUC ${Number(m.roc_auc||0).toFixed(3)} · PR-AUC ${m.pr_auc==null?'—':Number(m.pr_auc).toFixed(3)} · Brier ${Number(m.brier||0).toFixed(3)} · Balanced accuracy ${(Number(m.balanced_accuracy||0)*100).toFixed(1)}%</span></div>`}).join('')+`<div class="health-model-card"><strong>Гипотеза «после минуса будет плюс»</strong><span>P(win после loss) ${(Number(hyp.p_next_win_after_loss||0)*100).toFixed(1)}% · baseline ${(Number(hyp.baseline_next_win_probability||0)*100).toFixed(1)}%</span><span class="${hyp.supported_at_5pct?'':'alert'}">${hyp.supported_at_5pct?'подтверждена':'не подтверждена'} · p=${hyp.fisher_exact_greater_p_value==null?'—':Number(hyp.fisher_exact_greater_p_value).toFixed(3)}</span></div>`}
async function switchMode(){const current=$('heroMode').textContent.toLowerCase(),target=current==='live'?'paper':'live';if(target==='live'){toast('Проверяем LIVE','CLOB, баланс, allowance, стакан и локальная подпись заявки');const preflight=await fetch('/api/live-preflight',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const check=await preflight.json();if(!preflight.ok||!check.ready){const detail=check.detail||check;toast('LIVE не включён',detail.message||'Технический preflight не пройден');return}}const r=await fetch('/api/trading-mode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:target,canary:true})});const payload=await r.json();if(!r.ok){const detail=payload.detail||{},failures=detail.failures||[];toast(detail.message||'Переключение заблокировано',failures.join('; ')||'Не выполнены проверки безопасности');return}toast('Режим изменён',payload.message);await refresh()}
