function initializeDashboardSections(){const label=document.querySelector('label[for="liveScale"]');if(label)label.childNodes[0].textContent='Множитель суммы заявки ';const apply=$('applyLiveScale');if(apply)apply.textContent='Применить множитель';const openByDefault=new Set(['paper','market']);document.querySelectorAll('main > section.panel-section, main > section.two-col, main > section.three-col').forEach((section,index)=>{if(section.dataset.collapsible)return;section.dataset.collapsible='1';const title=section.querySelector('h2')?.textContent?.trim()||`Раздел ${index+1}`,body=document.createElement('div'),toggle=document.createElement('button'),closed=!openByDefault.has(section.id);body.className='collapsible-body';while(section.firstChild)body.appendChild(section.firstChild);toggle.type='button';toggle.className='section-collapse-toggle';toggle.setAttribute('aria-expanded',String(!closed));toggle.innerHTML=`<span>${esc(title)}</span><strong>${closed?'Развернуть +':'Свернуть −'}</strong>`;toggle.onclick=()=>{const nowClosed=section.classList.toggle('section-collapsed');toggle.setAttribute('aria-expanded',String(!nowClosed));toggle.querySelector('strong').textContent=nowClosed?'Развернуть +':'Свернуть −'};if(closed)section.classList.add('section-collapsed');section.append(toggle,body)})}
initializeDashboardSections();
const confidenceHelp=document.createElement('details');confidenceHelp.className='confidence-help';confidenceHelp.innerHTML='<summary>Как читать confidence и пятиступенчатый выход</summary><div><p><strong>Confidence</strong> — калиброванная вероятность выбранной стороны относительно Price to Beat, а не вероятность роста цены контракта. Для числовых моделей P(Up) и P(Down) нормируются симметрично, затем модельная вероятность смешивается с вероятностью рынка.</p><p><strong>&lt;72%</strong> — слабый сигнал; <strong>72–80%</strong> — умеренный; <strong>80–90%</strong> — сильный; <strong>≥90%</strong> — очень сильный. Итоговый вход выбирается моделью по net value, P(fill), стакану и риску; confidence сам по себе вход не гарантирует.</p><p><strong>Выход 1–5</strong> — последовательные частичные фиксации лимитными заявками. Порог вероятности удерживаемой стороны: 58% → 48% → 38% → 28% → 18%. Полный выход разрешается при сильном превосходстве CLOSE над HOLD; переворот позиции запрещён.</p></div>';const executionPanel=$('executionBody')?.closest('article');if(executionPanel)executionPanel.appendChild(confidenceHelp);
