function drawTradeMarkers(ctx,chart,x,y,pad,W,H){for(const event of tradeTimelineEvents(tradeReplayState.data||{})){if(event.t<tradeReplayState.viewStart||event.t>tradeReplayState.viewEnd)continue;const px=x(event.t);ctx.save();ctx.strokeStyle=event.color;ctx.globalAlpha=event.kind==='resolution'?.8:.65;ctx.setLineDash(event.kind==='submit'?[4,4]:[]);ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,H-pad.b);ctx.stroke();ctx.setLineDash([]);if(chart.kind==='probability'&&chart.id==='tradeMarketChart'&&Number.isFinite(event.v)){const py=y(event.v);ctx.fillStyle=event.color;ctx.globalAlpha=1;ctx.beginPath();if(event.kind==='submit'){ctx.moveTo(px,py-6);ctx.lineTo(px+6,py+5);ctx.lineTo(px-6,py+5)}else{ctx.arc(px,py,5,0,Math.PI*2)}ctx.fill();ctx.fillStyle='#e6edf7';ctx.font='11px Segoe UI';ctx.fillText(event.label,Math.min(W-160,Math.max(pad.l+3,px+7)),Math.max(pad.t+12,py-8))}ctx.restore()}}
