function renderTradeTooltip(canvas,chart,xPosition){const tooltip=canvas.parentElement.querySelector('.trade-tooltip');if(tradeReplayState.hoverTime==null){tooltip.hidden=true;return}const values=nearestTradeValues(chart,tradeReplayState.hoverTime),rect=canvas.getBoundingClientRect();tooltip.innerHTML=`<strong>${tradeFormatTime(tradeReplayState.hoverTime)}</strong>${values.map(({series,point,delta})=>{const action=point.raw?.action?` · ${esc(point.raw.action)}`:'';return `<span><i style="display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:${series.color}"></i>${esc(series.label)} <em>${tradeFormatValue(chart.kind,point.v)}</em><small>точка ${tradeFormatTime(point.t)} · Δ ${(delta/1000).toFixed(1)}с${action}</small></span>`}).join('')||'<span>Рядом нет сохранённых точек</span>'}`;tooltip.hidden=false;tooltip.style.left=`${Math.min(rect.width-340,Math.max(8,xPosition+12))}px`;tooltip.style.top='10px'}
function drawTradePanel(chart){const canvas=$(chart.id);if(!canvas)return;const{ctx,W,H}=setupTradeCanvas(canvas),pad={l:70,r:18,t:18,b:36},start=tradeReplayState.viewStart,end=tradeReplayState.viewEnd,[lo,hi]=tradeYRange(chart),range=Math.max(1e-9,hi-lo),x=t=>pad.l+(W-pad.l-pad.r)*(t-start)/Math.max(1,end-start),y=v=>H-pad.b-(H-pad.t-pad.b)*(v-lo)/range;ctx.clearRect(0,0,W,H);ctx.font='11px Segoe UI';ctx.lineWidth=1;for(let i=0;i<=4;i++){const py=pad.t+(H-pad.t-pad.b)*i/4,value=hi-range*i/4;ctx.strokeStyle='#1d2733';ctx.beginPath();ctx.moveTo(pad.l,py);ctx.lineTo(W-pad.r,py);ctx.stroke();ctx.fillStyle='#8794a5';ctx.fillText(tradeFormatValue(chart.kind,value),4,py+4)}for(let i=0;i<=5;i++){const time=start+(end-start)*i/5,px=x(time);ctx.strokeStyle='#141e29';ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,H-pad.b);ctx.stroke();ctx.fillStyle='#8794a5';const label=tradeFormatTime(time,false);ctx.fillText(label,Math.max(pad.l,Math.min(W-pad.r-38,px-19)),H-12)}if(chart.kind==='btc'&&Number.isFinite(Number(tradeReplayState.data?.target?.target_price))){const target=Number(tradeReplayState.data.target.target_price),py=y(target);ctx.strokeStyle='#70a7ff';ctx.setLineDash([7,5]);ctx.beginPath();ctx.moveTo(pad.l,py);ctx.lineTo(W-pad.r,py);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#70a7ff';ctx.fillText(`Price to Beat ${tradeFormatValue('btc',target)}`,pad.l+7,Math.max(pad.t+12,py-6))}if(chart.kind==='pnl'&&lo<=0&&hi>=0){ctx.strokeStyle='#526174';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(pad.l,y(0));ctx.lineTo(W-pad.r,y(0));ctx.stroke();ctx.setLineDash([])}const visible=chart.series.filter(series=>!tradeReplayState.hidden.has(series.key)&&series.points.some(point=>point.t>=start&&point.t<=end));for(const series of visible)drawTradePath(ctx,series,x,y);if(!visible.length){ctx.fillStyle='#8996a8';ctx.font='13px Segoe UI';ctx.fillText('Для этого графика нет сохранённых точек',pad.l+18,pad.t+34)}drawTradeMarkers(ctx,chart,x,y,pad,W,H);if(tradeReplayState.hoverTime!=null){const px=x(tradeReplayState.hoverTime);ctx.strokeStyle='#d8e0ea';ctx.globalAlpha=.7;ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,H-pad.b);ctx.stroke();ctx.globalAlpha=1;renderTradeTooltip(canvas,chart,px)}else renderTradeTooltip(canvas,chart,0);bindTradeCanvas(canvas,chart,pad,W)}
function redrawTradeCharts(){for(const chart of tradeReplayState.charts)drawTradePanel(chart)}
function scheduleTradeRedraw(){if(tradeReplayState.raf)return;tradeReplayState.raf=requestAnimationFrame(()=>{tradeReplayState.raf=0;redrawTradeCharts()})}
function setTradeRange(start,end,buttonId){const minSpan=5000;tradeReplayState.viewStart=Math.max(tradeReplayState.fullStart,Math.min(start,tradeReplayState.fullEnd-minSpan));tradeReplayState.viewEnd=Math.min(tradeReplayState.fullEnd,Math.max(end,tradeReplayState.viewStart+minSpan));document.querySelectorAll('.trade-range-buttons .control-btn').forEach(b=>b.classList.toggle('active',b.id===buttonId));scheduleTradeRedraw()}
function bindTradeCanvas(canvas,chart,pad,W){if(canvas.dataset.tradeBound)return;canvas.dataset.tradeBound='1';canvas.addEventListener('pointerdown',event=>{canvas.setPointerCapture(event.pointerId);tradeReplayState.drag={x:event.clientX,start:tradeReplayState.viewStart,end:tradeReplayState.viewEnd}});canvas.addEventListener('pointerup',()=>tradeReplayState.drag=null);canvas.addEventListener('pointercancel',()=>tradeReplayState.drag=null);canvas.addEventListener('pointermove',event=>{const rect=canvas.getBoundingClientRect(),usable=Math.max(1,rect.width-pad.l-pad.r);if(tradeReplayState.drag){const shift=(event.clientX-tradeReplayState.drag.x)/usable*(tradeReplayState.drag.end-tradeReplayState.drag.start),span=tradeReplayState.drag.end-tradeReplayState.drag.start;let start=tradeReplayState.drag.start-shift;start=Math.max(tradeReplayState.fullStart,Math.min(start,tradeReplayState.fullEnd-span));tradeReplayState.viewStart=start;tradeReplayState.viewEnd=start+span}else{const ratio=Math.max(0,Math.min(1,(event.clientX-rect.left-pad.l)/usable));tradeReplayState.hoverTime=tradeReplayState.viewStart+ratio*(tradeReplayState.viewEnd-tradeReplayState.viewStart)}scheduleTradeRedraw()});canvas.addEventListener('pointerleave',()=>{if(!tradeReplayState.drag){tradeReplayState.hoverTime=null;scheduleTradeRedraw()}});canvas.addEventListener('wheel',event=>{event.preventDefault();const rect=canvas.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(event.clientX-rect.left-pad.l)/Math.max(1,rect.width-pad.l-pad.r))),span=tradeReplayState.viewEnd-tradeReplayState.viewStart,factor=event.deltaY>0?1.25:.8,newSpan=Math.max(10000,Math.min(tradeReplayState.fullEnd-tradeReplayState.fullStart,span*factor)),center=tradeReplayState.viewStart+ratio*span;let start=center-ratio*newSpan;start=Math.max(tradeReplayState.fullStart,Math.min(start,tradeReplayState.fullEnd-newSpan));tradeReplayState.viewStart=start;tradeReplayState.viewEnd=start+newSpan;scheduleTradeRedraw()},{passive:false});canvas.addEventListener('dblclick',()=>setTradeRange(tradeReplayState.fullStart,tradeReplayState.fullEnd,'tradeRangeFull'))}
function renderTradeLegend(){const unique=new Map();for(const chart of tradeReplayState.charts)for(const series of chart.series)unique.set(series.key,series);$('tradeLegend').innerHTML=[...unique.values()].map(series=>`<button type="button" data-trade-series="${esc(series.key)}" class="${tradeReplayState.hidden.has(series.key)?'off':''}"><i style="background:${series.color}"></i>${esc(series.label)}</button>`).join('')+`<span><i style="background:#ffbe55"></i>LIMIT отправлен</span><span><i style="background:#70a7ff"></i>Фактический fill</span>`;$('tradeLegend').querySelectorAll('button').forEach(button=>button.onclick=()=>{const key=button.dataset.tradeSeries;tradeReplayState.hidden.has(key)?tradeReplayState.hidden.delete(key):tradeReplayState.hidden.add(key);renderTradeLegend();redrawTradeCharts()})}
function drawTrade(d){tradeReplayState.data=d;tradeReplayState.charts=buildTradeCharts(d);tradeReplayState.hidden.clear();const fallbackStart=tradeTime(d.position?.opened_at)||Date.now()-300000,fullStart=tradeTime(d.event_window?.start)||fallbackStart,fullEnd=tradeTime(d.event_window?.end)||fullStart+300000;tradeReplayState.fullStart=fullStart;tradeReplayState.fullEnd=Math.max(fullStart+1000,fullEnd);tradeReplayState.viewStart=fullStart;tradeReplayState.viewEnd=tradeReplayState.fullEnd;tradeReplayState.hoverTime=null;renderTradeLegend();redrawTradeCharts();const points=tradeReplayState.charts.flatMap(c=>c.series.flatMap(s=>s.points)),gaps=tradeReplayState.charts.flatMap(c=>c.series.flatMap(s=>{const result=[];for(let i=1;i<s.points.length;i++)result.push(s.points[i].t-s.points[i-1].t);return result})),maxGap=gaps.length?Math.max(...gaps)/1000:0,orders=d.orders||[],fills=orders.filter(x=>x.filled_at&&Number(x.shares||0)>0).length;$('tradeChartStatus').innerHTML=`${num(points.length)} точек · ${num(orders.length)} заявок · ${num(fills)} fills · max gap <span class="${maxGap>10?'trade-data-gap':''}">${maxGap.toFixed(1)}с</span> · без синтетической интерполяции`;setTradeRange(fullStart,tradeReplayState.fullEnd,'tradeRangeFull')}
$('tradeRangeFull')?.addEventListener('click',()=>tradeReplayState.data&&setTradeRange(tradeReplayState.fullStart,tradeReplayState.fullEnd,'tradeRangeFull'));
$('tradeRangeEntry')?.addEventListener('click',()=>{if(!tradeReplayState.data)return;const entry=tradeTime(tradeReplayState.data.position?.opened_at)||tradeReplayState.fullStart;setTradeRange(entry-60000,entry+60000,'tradeRangeEntry')});
$('tradeRangePosition')?.addEventListener('click',()=>{if(!tradeReplayState.data)return;const p=tradeReplayState.data.position||{},start=tradeTime(p.opened_at)||tradeReplayState.fullStart,end=(p.had_early_exit?tradeTime(p.closed_at):null)||tradeReplayState.fullEnd;setTradeRange(start-5000,end+5000,'tradeRangePosition')});
$('tradeResetZoom')?.addEventListener('click',()=>tradeReplayState.data&&setTradeRange(tradeReplayState.fullStart,tradeReplayState.fullEnd,'tradeRangeFull'));
async function loadTradeModern(){const key=$('tradeSelect').value,button=$('loadTrade');if(!key)return;button.disabled=true;button.textContent='Собираю точный replay…';try{const d=await json(`/api/trade/${key}`);currentTradeKey=key;const p=d.position||{},decision=d.decision||{},target=d.target||{},resolution=d.resolution||{},fees=d.fees||{},orders=d.orders||[],entries=orders.filter(x=>String(x.action||'').toUpperCase().startsWith('BUY')&&Number(x.shares||0)>0),exits=orders.filter(x=>['CLOSE','PARTIAL_CLOSE','SELL'].includes(String(x.action||'').toUpperCase())&&Number(x.shares||0)>0),firstEntry=entries[0]||{},lastExit=exits.at(-1)||{},entryDelay=firstEntry.submitted_at&&firstEntry.filled_at?Math.max(0,tradeTime(firstEntry.filled_at)-tradeTime(firstEntry.submitted_at)):null,exitLabels={open:'позиция открыта',held_to_resolution:'удержано до полного расчёта',early_full_exit:'ранний полный выход',early_partial_exit:'ранний частичный выход',partial_early_then_resolution:'частичный выход → остаток до расчёта',early_exit_submitted:'ранний выход отправлен'};const outcomeText=resolution.winning_outcome?`${resolution.winning_outcome} · ${resolution.selected_outcome_won?'ПОБЕДА':'ПОРАЖЕНИЕ'}`:'ещё не рассчитано',vsHold=resolution.early_exit_vs_hold_usdc;$('tradeMeta').innerHTML=detail('Режим',String(d.source||'').toUpperCase())+detail('Валидность',Number(p.execution_valid??1)===1?'VALID':`ИСКЛЮЧЕНА · ${p.invalid_reason||'invalid'}`)+detail('Сторона',p.outcome||'—')+detail('Финальный исход',outcomeText)+detail('Средняя цена входа',Number(p.average_price||0).toFixed(4))+detail('Лимит → первый fill',firstEntry.requested_price==null?'—':`${Number(firstEntry.requested_price).toFixed(4)} → ${firstEntry.filled_price==null?'не исполнен':Number(firstEntry.filled_price).toFixed(4)}`)+detail('Задержка первого fill',entryDelay==null?'—':`${entryDelay.toFixed(0)} ms`)+detail('Сумма входа',money(p.cost_usdc))+detail('Цена выхода',p.close_price==null?'—':Number(p.close_price).toFixed(4))+detail('Последний выходной fill',lastExit.filled_price==null?'—':`${Number(lastExit.filled_price).toFixed(4)} · ${Number(lastExit.shares||0).toFixed(3)} шт.`)+detail('Тип завершения',exitLabels[p.exit_timing]||p.exit_timing||'—')+detail('Фактический PnL',resolution.actual_pnl_usdc==null?money(p.realized_pnl_usdc||0):money(resolution.actual_pnl_usdc))+detail('HOLD до результата',resolution.hold_to_resolution_pnl_usdc==null?'—':money(resolution.hold_to_resolution_pnl_usdc))+detail('Ранний выход vs HOLD',vsHold==null?'не применимо':`${vsHold>=0?'+':''}${money(vsHold)}`)+detail('Комиссии по fills',money(fees.total_usdc||0))+detail('Price to Beat',target.target_price?`$${Number(target.target_price).toFixed(2)}`:'—')+detail('Entry confidence',decision.confidence==null?'—':`${(Number(decision.confidence)*100).toFixed(1)}%`)+detail('Entry-модель',decision.model_name||'—')+detail('Открыта',p.opened_at?new Date(p.opened_at).toLocaleString('ru-RU'):'—')+detail('Закрыта',p.closed_at?new Date(p.closed_at).toLocaleString('ru-RU'):'позиция открыта')+detail('Обоснование',decision.reason||'—');drawTrade(d)}finally{button.disabled=false;button.textContent='Построить разбор'}}
loadTrade=loadTradeModern;

let refreshInFlight=false,tradesRefreshInFlight=false,lastTradesRefresh=0;
async function refreshTradeList(force=false){if(tradesRefreshInFlight||(!force&&Date.now()-lastTradesRefresh<60000))return;tradesRefreshInFlight=true;try{populateTrades(await json('/api/trades?limit=60'));lastTradesRefresh=Date.now()}catch(e){console.error(e)}finally{tradesRefreshInFlight=false}}
async function refresh(forceTrades=false){if(refreshInFlight)return;refreshInFlight=true;try{const [o,t]=await Promise.all([json('/api/overview'),json('/api/timeseries?minutes=15')]);renderOverview(o);drawChart(t.series);refreshTradeList(forceTrades)}catch(e){$('healthDot').className='dot error';$('healthText').textContent='Ошибка dashboard';console.error(e)}finally{refreshInFlight=false}}$('loadTable').addEventListener('click',()=>loadTable().catch(console.error));$('loadTrade').addEventListener('click',()=>loadTrade().catch(e=>toast('График сделки',e.message)));$('modeToggle').addEventListener('click',()=>switchMode().catch(e=>toast('Ошибка',e.message)));$('liveScale').addEventListener('input',updateLiveScalePreview);$('applyLiveScale').addEventListener('click',()=>setLiveScale().catch(e=>toast('Ошибка',e.message)));$('stopTrading').addEventListener('click',()=>controlTrading('stop').catch(e=>toast('Ошибка',e.message)));$('resumeTrading').addEventListener('click',()=>controlTrading('resume').catch(e=>toast('Ошибка',e.message)));$('newPaperRun').addEventListener('click',()=>controlTrading('new_session').catch(e=>toast('Ошибка',e.message)));$('applyEntryModel').addEventListener('click',()=>switchModel('entry').catch(e=>toast('Ошибка',e.message)));$('applyExitModel').addEventListener('click',()=>switchModel('exit').catch(e=>toast('Ошибка',e.message)));$('refreshNow').addEventListener('click',()=>refresh(true));$('exportNow').addEventListener('click',()=>exportNow().catch(e=>toast('Ошибка экспорта',e.message)));$('toggleMetricHelp').addEventListener('click',()=>{$('metricHelp').hidden=!$('metricHelp').hidden});$('comparisonSort').addEventListener('change',()=>lastOverview&&renderModelComparison(lastOverview.models||{}));$('offlineSort').addEventListener('change',()=>lastOverview&&renderOfflineComparison(lastOverview.models||{}));$('equityRange').addEventListener('change',()=>drawModelEquity(currentEquityCurves));$('equityReset').addEventListener('click',()=>{$('equityRange').value='0';visibleEquityModels=new Set(Object.keys(currentEquityCurves));renderModelEquity(currentEquityCurves)});$('modelEquityChart').addEventListener('mousemove',equityHover);$('modelEquityChart').addEventListener('mouseleave',()=>{$('equityTooltip').hidden=true});refresh();window.addEventListener('resize',()=>{json('/api/timeseries?minutes=15').then(x=>drawChart(x.series));drawModelEquity(currentEquityCurves);if(currentTradeKey&&tradeReplayState.data)scheduleTradeRedraw()});
// Быстрый цикл отображения: backend-кэш ограничивает нагрузку, UI не отстаёт на минуту.
// Тяжёлый сводный запрос обновляем достаточно часто для торговли, но без лавины
// параллельных вычислений офлайн-метрик на слабом ноутбуке.
setInterval(refresh,20000);
