// Единая лента событий: фактические позиции и осознанные пропуски.
let latestTradeList={trades:[],skipped_events:[]};
function conciseDecisionReason(value){const text=String(value||'Причина не записана');const low=text.toLowerCase();if(low.includes('price to beat')||low.includes('target'))return 'Не получен официальный Price to Beat';if(low.includes('reference')||low.includes('медиан'))return 'Нет свежей текущей цены BTC (Bybit/OKX/Pyth)';if(low.includes('confidence')||low.includes('uncertain'))return 'Уверенность модели недостаточна';if(low.includes('edge')||low.includes('utility')||low.includes('value'))return 'Ожидаемая прибыль не покрывает цену и риск';if(low.includes('price')||low.includes('ask')||low.includes('range'))return 'Цена контракта вне выгодного диапазона';if(low.includes('position')||low.includes('already'))return 'Уже есть позиция в событии';if(low.includes('risk')||low.includes('stop')||low.includes('cooldown'))return 'Торговый предохранитель / пауза';if(low.includes('fill')||low.includes('liquid')||low.includes('book'))return 'Нет подтверждённого исполнения по стакану';return text.length>150?`${text.slice(0,147)}…`:text}
function renderEventResults(){const box=$('paperPositions'),filter=$('positionFilter')?.value||'all',mode=String(lastOverview?.trading?.mode||'paper');let entered=(latestTradeList.trades||[]).filter(x=>x.source===mode);let skipped=latestTradeList.skipped_events||[];let rows=[];if(filter!=='skipped')rows.push(...entered.map(x=>({...x,_kind:'entered',_time:x.opened_at})));if(filter!=='entered')rows.push(...skipped.map(x=>({...x,_kind:'skipped',_time:x.observed_at})));rows.sort((a,b)=>String(b._time||'').localeCompare(String(a._time||'')));rows=rows.slice(0,60);box.innerHTML=rows.length?rows.map(x=>{if(x._kind==='skipped')return `<div class="activity-row skipped-event"><strong>НЕ ВОШЛА · ${esc(x.action||'WAIT')}</strong><span>${esc(conciseDecisionReason(x.reason))}<br>confidence ${(Number(x.confidence||0)*100).toFixed(1)}% · P Up ${x.predicted_up_probability==null?'—':(Number(x.predicted_up_probability)*100).toFixed(1)+'%'} · P Down ${x.predicted_down_probability==null?'—':(Number(x.predicted_down_probability)*100).toFixed(1)+'%'}</span><small>${eventLink(x)}<br>${esc(x.model_name||'unknown')}</small><strong class="muted">SKIP</strong></div>`;const pnl=Number(x.marked_pnl_usdc||0),shares=Number(x.shares||0),cost=Number(x.cost_usdc||0),fee=Number(x.fees_usdc||0),fill=Number(x.average_price||0),effective=shares>0?cost/shares:null;return `<div class="activity-row"><strong>${esc(x.outcome)} · ${esc(x.status)} · ВОШЛА</strong><span>Вход fill ${fill.toFixed(3)}${effective!=null&&Math.abs(effective-fill)>0.00005?` · эфф. ${effective.toFixed(4)}`:''} · ${money(cost)}<br>Выход ${x.close_price==null?'—':Number(x.close_price).toFixed(3)} · комиссия ${money(fee)}</span><small>${eventLink(x)}<br>${esc(conciseDecisionReason(x.entry_reason))} · ${esc(x.entry_model||'unknown')}</small><strong class="${pnl>0?'positive':pnl<0?'negative':''}">${x.status==='open'?'OPEN':money(pnl)}</strong></div>`}).join(''):'<p class="empty">Событий для выбранного фильтра нет</p>'}
const populateTradesV22=populateTrades;
populateTrades=function(payload){populateTradesV22(payload);latestTradeList=payload||latestTradeList;renderEventResults()};
$('positionFilter')?.addEventListener('change',renderEventResults);
